WITH o AS MATERIALIZED (SELECT x.object_id,x.role,x.canonical_length,x.group_number,x.record_number,x.pack_id,x.ancestors FROM unnest($1::bytea[],$2::bigint[]) k(i,k) CROSS JOIN LATERAL (SELECT * FROM {schema}.object_location x WHERE ('x'||encode(substring(x.object_id FROM 1 FOR 8),'hex'))::bit(64)::bigint=k.k AND x.object_id=k.i OFFSET 0) x) SELECT 0::integer AS kind,CASE WHEN octet_length(o.object_id)=32 THEN o.object_id END AS object_id,o.role::bigint AS role,o.canonical_length::bigint AS canonical_length,o.group_number::bigint AS group_number,o.record_number::bigint AS record_number,o.pack_id,o.ancestors AS bytes,NULL::bigint AS domain,NULL::bytea AS digest,NULL::bigint AS length FROM o UNION ALL SELECT 1,NULL,NULL,NULL,NULL,NULL,p.pack_id,p.directory,p.domain,CASE WHEN octet_length(p.digest)=32 THEN p.digest END,p.length FROM {schema}.pack p WHERE p.pack_id=ANY(ARRAY(SELECT DISTINCT o.pack_id FROM o))
